drills.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("each notifier reports its channel through the base type", () =>
{
    var all = new List<Notifier> { new EmailNotifier(), new SmsNotifier() };
    Eq(all.Select(n => n.Channel).ToList(), new[] { "email", "sms" });
});

Test("the email notifier keeps the base format", () =>
    Eq(new EmailNotifier().Format("Order 42 shipped"), "[email] Order 42 shipped"));

Test("a short SMS uses the base format", () =>
    Eq(((Notifier)new SmsNotifier()).Format("Order 42 shipped"), "[sms] Order 42 shipped"));

Test("a long SMS is cut to 30 characters with an ellipsis", () =>
{
    var text = new SmsNotifier().Format("Your order 4242 has shipped and arrives Friday");
    Eq(text.Length, 30);
    Eq(text, "[sms] Your order 4242 has shi…");
});

Test("exactly 30 characters is not cut (boundary)", () =>
{
    var msg = new string('x', 24);
    Eq(new SmsNotifier().Format(msg), "[sms] " + msg);
});

